from __future__ import absolute_import

import time

from selenium.webdriver.common.by import By
from taf.selenium.sbts.common.exceptions import ParamValueError
from taf.selenium.sbts.pages import v24r2, v20b, v23r4
from taf.selenium.sbts.pages.modals import IpTrafficCapturePasswordInputModal
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.panels.view import ViewPanel


class Diagnostic(v24r2.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._ip_traffic_capturing = IpTrafficCapturingPage(driver, download_checker)
        self._pim_desensitization = PimDesensitizationPage(driver, download_checker)
        self._downlink = TestModelsNRDownlinkPage(driver)
        self._lte_downlink = TestModelsLTEDownlinkPage(driver, download_checker)
        self._diagnostic_check = DiagnosticCheckPage(driver)

    @property
    def pim_desensitization(self):
        return self._pim_desensitization


class IpTrafficCapturingPage(v20b.diagnostic.IpTrafficCapturingPage):
    def __init__(self, driver, download_checker):
        super(IpTrafficCapturingPage, self).__init__(driver, download_checker)
        self._ip_traffic_capturing_view_panel = IpTrafficCapturingPageViewPanel(driver, download_checker)

    def download_ip_traffic_capturing_file(self, password, download_timeout=60):
        if password is None:
            raise ParamValueError("password can not be None")
        return self._ip_traffic_capturing_view_panel.download_ip_traffic_capturing_file(password, download_timeout)


class IpTrafficCapturingPageViewPanel(v20b.diagnostic.IpTrafficCapturingPageViewPanel):
    _DOWNLOAD_FILE_COMPLETED = "download completed"

    def __int__(self, driver, download_checker):
        super(IpTrafficCapturingPageViewPanel, self).__init__(driver, download_checker)

    def download_ip_traffic_capturing_file(self, password, download_timeout=60):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._DOWNLOAD_FILE_BUTTON_XPATH), download_timeout)
        modal = IpTrafficCapturePasswordInputModal(self.driver)
        modal.wait_until_password_input_modal_appear()
        modal.input_password(password)
        modal.close()

        self.wait_for_text_present_in_element((By.XPATH, self._IP_TRAFFIC_CAPTURING_PROGRESS_MEG),
                                              self._DOWNLOAD_FILE_COMPLETED,
                                              download_timeout)
        return self.download_files(start_time, download_timeout)


class PimDesensitizationPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Diagnostic", "RF Monitoring", "PIM Desensitization"]

    def __init__(self, driver, download_checker):
        super(PimDesensitizationPage, self).__init__(driver)
        self._view_panel = PimDesensitizationPageViewPanel(driver, download_checker)

    def start_pim_desensitization(self, technology, antenna, cell_power_table, download_timeout=300):
        return self._view_panel.start_pim_desensitization(technology, antenna, cell_power_table, download_timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class PimDesensitizationPageViewPanel(ViewPanel):
    LTE = '//technology-radio-group//*[text()="LTE technology"]/preceding-sibling::input'
    WCDMA = '//technology-radio-group//*[text()="WCDMA technology"]/preceding-sibling::input'
    TEST_ANTENNA_BUTTON = '//*[@class="tested-antennas"]//button'
    TEST_ANTENNA = '//*[@class="tested-antennas"]//li//span'
    POWER_BUTTON = '//span[span[text()="{}"]]/ancestor::tr//td[contains(@class, "pim-downlink-power")]//button'
    POWER_OPTION = ('//span[span[text()="{}"]]/ancestor::tr'
                    '//td[contains(@class, "pim-downlink-power")]//li//span')
    START = '//rf-monitoring-progress//button[contains(text(), "Start")]'
    DOWNLOADING = 'Testing and downloading files from BTS'
    DOWNLOADED = 'Download completed and file saved'
    PROGRESS = '//rf-monitoring-progress//div[contains(@class, "rf-monitoring-progress-info")]'

    def __init__(self, driver, download_checker):
        super(PimDesensitizationPageViewPanel, self).__init__(driver, download_checker)

    def start_pim_desensitization(self, technology, antenna, cell_power_table, download_timeout=300):
        if "LTE" in technology.upper():
            self.click_enabled_element((By.XPATH, self.LTE))
        if "WCDMA" in technology.upper():
            self.click_enabled_element((By.XPATH, self.WCDMA))

        self.select_element_from_dropdown_list_by_text_and_click(
            antenna,
            (By.XPATH, self.TEST_ANTENNA_BUTTON),
            (By.XPATH, self.TEST_ANTENNA)
        )

        for cell, power in cell_power_table.items():
            self.select_element_from_dropdown_list_by_text_and_click(
                power,
                (By.XPATH, self.POWER_BUTTON.format(cell)),
                (By.XPATH, self.POWER_OPTION.format(cell))
            )

        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, self.START))
        self.wait_for_text_present_in_element((By.XPATH, self.PROGRESS), self.DOWNLOADING)
        return self.download_files(start_time, download_timeout)


class TestModelsNRDownlinkPage(v24r2.diagnostic.TestModelsNRDownlinkPage):
    def __init__(self, driver):
        super(TestModelsNRDownlinkPage, self).__init__(driver)
        self._view_panel = TestModelsNRDownlinkPageViewPanel(driver)

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None,
                   power_backoff=None, ru_mode=None, mimo_rank=None, enable_vswr=False, level_of_load_slot_wise=None):
        return self._view_panel.start_test(local_cell=local_cell, test_model=test_model, p_max=p_max,
                                           timeout=timeout, polarization=polarization,
                                           physical_cell_id=physical_cell_id,
                                           beam_id=beam_id, nrarfcn=nrarfcn, type_of_load=type_of_load,
                                           level_of_load_burst=level_of_load_burst,
                                           level_of_load_flat=level_of_load_flat,
                                           spec_ssb_beam_pattern=spec_ssb_beam_pattern, power_backoff=power_backoff,
                                           ru_mode=ru_mode, mimo_rank=mimo_rank, enable_vswr=enable_vswr,
                                           level_of_load_slot_wise=level_of_load_slot_wise,
                                           nrarfcn_downlink=nrarfcn_downlink, nrarfcn_uplink=nrarfcn_uplink)

    def get_vswr_monitored_value(self):
        return self._view_panel.get_vswr_monitored_value()


class TestModelsNRDownlinkPageViewPanel(v24r2.diagnostic.TestModelsNRDownlinkPageViewPanel):
    _LEVEL_OF_LOAD_SLOT_WISE_LIST_BUTTON_XPATH = '//div[contains(text(), "Level of load slot")]/parent::*//button'
    _LEVEL_OF_LOAD_SLOT_WISE_LIST_OPTIONS_XPATH = '//div[contains(text(), "Level of load slot")]/parent::*//ul//li'

    def _configure_downlink_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                                 beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None,
                                 type_of_load=None, level_of_load_flat=None, level_of_load_burst=None,
                                 spec_ssb_beam_pattern=None, power_backoff=None, ru_mode=None, mimo_rank=None,
                                 enable_vswr=False, level_of_load_slot_wise=None):
        super(TestModelsNRDownlinkPageViewPanel, self)._configure_downlink_test(
            local_cell=local_cell,
            test_model=test_model,
            p_max=p_max,
            timeout=timeout,
            polarization=polarization,
            physical_cell_id=physical_cell_id,
            beam_id=beam_id,
            nrarfcn_downlink=nrarfcn_downlink,
            nrarfcn_uplink=nrarfcn_uplink,
            nrarfcn=nrarfcn,
            type_of_load=type_of_load,
            level_of_load_flat=level_of_load_flat,
            level_of_load_burst=level_of_load_burst,
            spec_ssb_beam_pattern=spec_ssb_beam_pattern,
            power_backoff=power_backoff,
            ru_mode=ru_mode,
            mimo_rank=mimo_rank,
            enable_vswr=enable_vswr
        )

        if level_of_load_slot_wise is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                level_of_load_slot_wise,
                (By.XPATH, self._LEVEL_OF_LOAD_SLOT_WISE_LIST_BUTTON_XPATH),
                (By.XPATH, self._LEVEL_OF_LOAD_SLOT_WISE_LIST_OPTIONS_XPATH),
                timeout
            )

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None,
                   power_backoff=None, ru_mode=None, mimo_rank=None, enable_vswr=False, level_of_load_slot_wise=None):
        timeout = int(timeout)
        self._configure_downlink_test(local_cell=local_cell,
                                      test_model=test_model,
                                      p_max=p_max,
                                      timeout=timeout,
                                      polarization=polarization,
                                      physical_cell_id=physical_cell_id,
                                      beam_id=beam_id,
                                      nrarfcn_downlink=nrarfcn_downlink,
                                      nrarfcn_uplink=nrarfcn_uplink,
                                      nrarfcn=nrarfcn,
                                      type_of_load=type_of_load,
                                      level_of_load_flat=level_of_load_flat,
                                      level_of_load_burst=level_of_load_burst,
                                      spec_ssb_beam_pattern=spec_ssb_beam_pattern,
                                      power_backoff=power_backoff,
                                      ru_mode=ru_mode,
                                      mimo_rank=mimo_rank,
                                      enable_vswr=enable_vswr,
                                      level_of_load_slot_wise=level_of_load_slot_wise)
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)


class TestModelsLTEDownlinkPage(v24r2.diagnostic.TestModelsLTEDownlinkPage):
    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPage, self).__init__(driver, download_checker)
        self._view_panel = TestModelsLTEDownlinkPageViewPanel(driver, download_checker)

    def start_lte_downlink_test(self, local_cell, test_model, physical_cell_id=None, ul_dl_configuration=None,
                                timeout=60, level_of_load=None):
        self._view_panel.start_lte_downlink_test(local_cell=local_cell,
                                                 test_model=test_model,
                                                 physical_cell_id=physical_cell_id,
                                                 ul_dl_configuration=ul_dl_configuration,
                                                 timeout=timeout,
                                                 level_of_load=level_of_load)


class TestModelsLTEDownlinkPageViewPanel(v24r2.diagnostic.TestModelsLTEDownlinkPageViewPanel):
    _LEVEL_OF_LOAD_BUTTON_XPATH = '//div[contains(text(), "Level of load")]/parent::*//p-dropdown'
    _LEVEL_OF_LOAD_OPTIONS_XPATH = '//ul[@role="listbox"]//li'

    def __init__(self, driver, download_checker):
        super(TestModelsLTEDownlinkPageViewPanel, self).__init__(driver, download_checker)

    def start_lte_downlink_test(self, local_cell, test_model, physical_cell_id=None,
                                ul_dl_configuration=None, timeout=60, level_of_load=None):
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            test_model,
            (By.XPATH, self._TEST_MODEL_LIST_BUTTON_XPATH),
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        if physical_cell_id:
            self.insert_text_to_enabled_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH),
                                                physical_cell_id,
                                                timeout)
        if ul_dl_configuration is not None:
            self.click_enabled_element((By.XPATH, self._UL_DL_CONFIGURATION_XPATH.format(ul_dl_configuration)), timeout)

        if level_of_load is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                level_of_load,
                (By.XPATH, self._LEVEL_OF_LOAD_BUTTON_XPATH),
                (By.XPATH, self._LEVEL_OF_LOAD_OPTIONS_XPATH),
                timeout
            )
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)


class DiagnosticCheckPage(v23r4.DiagnosticCheckPage):

    def __init__(self, driver):
        super(DiagnosticCheckPage, self).__init__(driver)
        self._view_panel = DiagnosticCheckPageViewPanel(driver)


class DiagnosticCheckPageViewPanel(v23r4.DiagnosticCheckPageViewPanel):

    _GET_REPORT_BUTTON = '//cem-operation-button//button[*[text()="Get Report"]]'
    _STARTING_STATUS = '//ot-instruction//*[contains(text(), "Diagnostic check ongoing")]'
    _START_SUCCEEDED_STATUS = '//ot-instruction//*[contains(text(), "Diagnostic check succeeded")]'
    _GET_REPORT_STATUS = '//ot-instruction//*[text()="Get report succeeded"]'
